/*!
 * @file
 * @brief Bridge to the "Tracker Calibration" app (fbt-calibrator) for Monado.
 *
 * Under SteamVR the calibrator is a driver that rewrites tracker poses. Monado cannot load such a
 * driver, so the same job is done here, where Lighthouse poses enter Monado:
 *  - every device publishes its REAL pose (Monado room space) to /dev/shm/fbtcal-devices-v2;
 *  - trackers listed in the app's slots (/dev/shm/fbtcal-v1, same layout as the SteamVR driver)
 *    get final = real * offset (device-local) or a fixed override pose (VRChat any-pose calibration).
 * Both files are plain shared memory; nothing happens until the app has created the slot file.
 */
#pragma once

#include "xrt/xrt_defines.h"
#include "math/m_api.h"

#include <atomic>
#include <cmath>
#include <cstdint>
#include <cstring>
#include <ctime>
#include <fcntl.h>
#include <mutex>
#include <string>
#include <sys/mman.h>
#include <sys/stat.h>
#include <unistd.h>
#include <unordered_map>

namespace fbtcal {

constexpr uint32_t SLOT_MAGIC = 0x46425431u; // "FBT1", written by the app
constexpr uint32_t DEV_MAGIC = 0x46424d32u;  // "FBM2"
constexpr int MAX_SLOTS = 8;
constexpr int MAX_DEVS = 24;

enum Mode : uint32_t { PASSTHROUGH = 0, OFFSET = 1, OVERRIDE = 2, BALANCED = 3 };

/*!
 * BALANCED (the waist, 2026-11-14 04:10): like OFFSET, but the sideways roll a side-of-belt tracker picks
 * up FROM SITTING is taken off: ovPos[0] = that roll (rad, learned while she sat upright), ovPos[1] = the
 * pelvis tilt it had then (rad). The share removed grows with how far the pelvis is tilted back now
 * (0 standing, all of it sitting), so real sideways leans still reach the avatar (removing all roll, as
 * level_roll did, broke the avatar when she leaned). Mirrored in app/fbtcal/body.py sit_fix().
 */
inline void
sit_fix(const xrt_vec3 &pivot, xrt_pose &fin, float roll_bias, float sit_pitch)
{
	if (sit_pitch <= 1e-3f) {
		return;
	}
	xrt_vec3 fwd{0.f, 0.f, -1.f};
	math_quat_rotate_vec3(&fin.orientation, &fwd, &fwd);
	const float pitch = std::asin(std::fmax(-1.f, std::fmin(1.f, fwd.y)));
	const float share = std::fmax(0.f, std::fmin(1.f, pitch / sit_pitch));
	const float a = -roll_bias * share;
	const float s = std::sin(a / 2.f);
	xrt_quat corr{-fwd.x * s, -fwd.y * s, -fwd.z * s, std::cos(a / 2.f)};
	math_quat_normalize(&corr);
	xrt_vec3 arm{fin.position.x - pivot.x, fin.position.y - pivot.y, fin.position.z - pivot.z};
	math_quat_rotate_vec3(&corr, &arm, &arm);
	fin.position = {pivot.x + arm.x, pivot.y + arm.y, pivot.z + arm.z};
	xrt_quat q;
	math_quat_rotate(&corr, &fin.orientation, &q);
	fin.orientation = q;
}

/*!
 * (old, unused) level_roll: removed ALL sideways roll. A tracker worn on
 * the side of the belt tilts with the flesh and clothes when she sits (≈8° measured 2026-11-14), and the
 * long lever to the body centre turned that into the whole body sliding sideways. Forward/back tilt and
 * turning are kept. The point turns about the tracker, so the tracker itself stays where it is.
 * Mirrored in app/fbtcal/body.py level_roll() — keep both the same.
 */
inline void
level_roll(const xrt_vec3 &pivot, xrt_pose &fin)
{
	xrt_vec3 fwd{0.f, 0.f, -1.f};
	math_quat_rotate_vec3(&fin.orientation, &fwd, &fwd);
	xrt_vec3 up{0.f, 1.f, 0.f};
	xrt_vec3 right;
	math_vec3_cross(&fwd, &up, &right);
	const float n = std::sqrt(right.x * right.x + right.y * right.y + right.z * right.z);
	if (n < 1e-3f) {
		return; // facing straight up or down: no sideways direction to level
	}
	right = {right.x / n, right.y / n, right.z / n};
	xrt_vec3 back{-fwd.x, -fwd.y, -fwd.z};
	xrt_quat level;
	math_quat_from_plus_x_z(&right, &back, &level);
	xrt_quat inv, corr;
	math_quat_invert(&fin.orientation, &inv);
	math_quat_rotate(&level, &inv, &corr);
	xrt_vec3 arm{fin.position.x - pivot.x, fin.position.y - pivot.y, fin.position.z - pivot.z};
	math_quat_rotate_vec3(&corr, &arm, &arm);
	fin.position = {pivot.x + arm.x, pivot.y + arm.y, pivot.z + arm.z};
	fin.orientation = level;
}
enum Kind : uint32_t { NONE = 0, HMD = 1, LEFT = 2, RIGHT = 3, TRACKER = 4, OTHER = 5 };

#pragma pack(push, 8)
struct Slot { // written by the app (fbtcal_shm.h FbtcalSlot)
	char serial[64];
	uint32_t mode;
	uint32_t _pad;
	double offPos[3];
	double offRot[4]; // w x y z
	double ovPos[3];
	double ovRot[4];
};
struct SlotFile {
	uint32_t magic;
	uint32_t appGen; // seqlock, odd while the app writes
	uint64_t appHeartbeatNs;
	uint64_t driverHeartbeatNs;
	Slot slots[MAX_SLOTS];
};
struct Dev { // written here
	char serial[64];
	uint32_t seq; // seqlock, odd while writing
	uint32_t kind;
	uint32_t valid;
	uint32_t _pad;
	uint64_t timeNs;
	double pos[3];
	double rot[4]; // w x y z, the REAL pose
	double fpos[3];
	double frot[4]; // w x y z, the pose apps get (after the calibration offset)
};
struct DevFile {
	uint32_t magic;
	uint32_t _pad;
	uint64_t heartbeatNs;
	Dev devs[MAX_DEVS];
};
#pragma pack(pop)

inline uint64_t
now_ns()
{
	timespec ts;
	clock_gettime(CLOCK_MONOTONIC, &ts);
	return uint64_t(ts.tv_sec) * 1000000000ull + uint64_t(ts.tv_nsec);
}

class Bridge
{
public:
	static Bridge &
	get()
	{
		static Bridge b;
		return b;
	}

	//! Publish the real pose of a device (valid=false: it went dark).
	void
	publish(const char *serial, uint32_t kind, bool valid, const xrt_pose &p, const xrt_pose &fin,
	        uint32_t inputs = 0)
	{
		if (!devs_) {
			return;
		}
		Dev *d = slot_for(serial);
		if (!d) {
			return;
		}
		d->seq++; // odd
		std::atomic_thread_fence(std::memory_order_release);
		d->kind = kind;
		d->valid = valid ? 1 : 0;
		d->_pad = inputs; // input activity counter (was unused padding)
		d->timeNs = now_ns();
		d->pos[0] = p.position.x;
		d->pos[1] = p.position.y;
		d->pos[2] = p.position.z;
		d->rot[0] = p.orientation.w;
		d->rot[1] = p.orientation.x;
		d->rot[2] = p.orientation.y;
		d->rot[3] = p.orientation.z;
		d->fpos[0] = fin.position.x;
		d->fpos[1] = fin.position.y;
		d->fpos[2] = fin.position.z;
		d->frot[0] = fin.orientation.w;
		d->frot[1] = fin.orientation.x;
		d->frot[2] = fin.orientation.y;
		d->frot[3] = fin.orientation.z;
		std::atomic_thread_fence(std::memory_order_release);
		d->seq++; // even
		devs_->heartbeatNs = d->timeNs;
	}

	//! If the app asked for it, replace/offset the pose of this tracker. Returns the mode applied (0 = none).
	uint32_t
	apply(const char *serial, xrt_pose &p, xrt_vec3 *lin_vel = nullptr, const xrt_vec3 *ang_vel = nullptr)
	{
		if (!open_slots()) {
			return 0;
		}
		Slot s;
		bool found = false;
		uint64_t hb = 0;
		for (int tries = 0; tries < 4 && !found; ++tries) {
			uint32_t g0 = slots_->appGen;
			if (g0 & 1) {
				continue;
			}
			std::atomic_thread_fence(std::memory_order_acquire);
			hb = slots_->appHeartbeatNs;
			bool hit = false;
			for (int i = 0; i < MAX_SLOTS; ++i) {
				if (slots_->slots[i].serial[0] && std::strncmp(slots_->slots[i].serial, serial, 63) == 0) {
					s = slots_->slots[i];
					hit = true;
					break;
				}
			}
			std::atomic_thread_fence(std::memory_order_acquire);
			if (slots_->appGen == g0) {
				if (!hit) {
					return 0;
				}
				found = true;
			}
		}
		if (!found) {
			return 0;
		}
		const bool app_alive = hb != 0 && now_ns() - hb < 2000000000ull;
		if (s.mode == OVERRIDE && app_alive) {
			p.position = {float(s.ovPos[0]), float(s.ovPos[1]), float(s.ovPos[2])};
			p.orientation = {float(s.ovRot[1]), float(s.ovRot[2]), float(s.ovRot[3]), float(s.ovRot[0])};
			return OVERRIDE;
		}
		if (s.mode == OFFSET || s.mode == OVERRIDE || s.mode == BALANCED) {
			xrt_pose off;
			off.position = {float(s.offPos[0]), float(s.offPos[1]), float(s.offPos[2])};
			off.orientation = {float(s.offRot[1]), float(s.offRot[2]), float(s.offRot[3]), float(s.offRot[0])};
			if (lin_vel != nullptr && ang_vel != nullptr) {
				// the point moves faster than the tracker while it turns: v += w x (R * lever), so that
				// the pose predicted ahead (the app asks for a moment in the future) follows the real motion
				xrt_vec3 arm, extra;
				math_quat_rotate_vec3(&p.orientation, &off.position, &arm);
				math_vec3_cross(ang_vel, &arm, &extra);
				math_vec3_accum(&extra, lin_vel);
			}
			const xrt_vec3 tracker = p.position;
			math_pose_transform(&p, &off, &p);
			if (s.mode == BALANCED) {
				sit_fix(tracker, p, float(s.ovPos[0]), float(s.ovPos[1]));
				return BALANCED;
			}
			return OFFSET;
		}
		return 0;
	}

private:
	Bridge()
	{
		int fd = shm_open("/fbtcal-devices-v2", O_RDWR | O_CREAT, 0600);
		if (fd < 0) {
			return;
		}
		if (ftruncate(fd, sizeof(DevFile)) == 0) {
			void *m = mmap(nullptr, sizeof(DevFile), PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
			if (m != MAP_FAILED) {
				devs_ = static_cast<DevFile *>(m);
				if (devs_->magic != DEV_MAGIC) {
					std::memset(devs_, 0, sizeof(DevFile));
					devs_->magic = DEV_MAGIC;
				}
			}
		}
		close(fd);
	}

	//! The slot file is created by the app; map it as soon as it exists (read-only is enough).
	bool
	open_slots()
	{
		if (slots_) {
			return true;
		}
		uint64_t t = now_ns();
		if (t - last_try_ < 1000000000ull) {
			return false;
		}
		last_try_ = t;
		int fd = shm_open("/fbtcal-v1", O_RDONLY, 0);
		if (fd < 0) {
			return false;
		}
		struct stat st;
		if (fstat(fd, &st) == 0 && size_t(st.st_size) >= sizeof(SlotFile)) {
			void *m = mmap(nullptr, sizeof(SlotFile), PROT_READ, MAP_SHARED, fd, 0);
			if (m != MAP_FAILED && static_cast<SlotFile *>(m)->magic == SLOT_MAGIC) {
				slots_ = static_cast<SlotFile *>(m);
			} else if (m != MAP_FAILED) {
				munmap(m, sizeof(SlotFile));
			}
		}
		close(fd);
		return slots_ != nullptr;
	}

	Dev *
	slot_for(const char *serial)
	{
		std::lock_guard lk(mut_);
		auto it = index_.find(serial);
		if (it != index_.end()) {
			return &devs_->devs[it->second];
		}
		if (next_ >= MAX_DEVS) {
			return nullptr;
		}
		int i = next_++;
		index_.emplace(serial, i);
		std::strncpy(devs_->devs[i].serial, serial, 63);
		return &devs_->devs[i];
	}

	DevFile *devs_ = nullptr;
	SlotFile *slots_ = nullptr;
	uint64_t last_try_ = 0;
	std::mutex mut_;
	std::unordered_map<std::string, int> index_;
	int next_ = 0;
};

} // namespace fbtcal
